#[must_use]
pub fn get_structure_template(path: &str) -> Option<&'static StaticStructureTemplate> {
    TEMPLATE_INDEX
        .binary_search_by_key(&path, |&(key, _)| key)
        .ok()
        .map(|i| TEMPLATES[TEMPLATE_INDEX[i].1])
}
